{"edits":[{"old":"FUNCTION_BLOCK AlarmHysteresis
VAR_INPUT
    Value       : REAL;
    hiLevel     : REAL;
    loLevel     : REAL;
    hystWindow  : REAL;
END_VAR
VAR_OUTPUT
    hiAlarm     : BOOL := FALSE;
    loAlarm     : BOOL := FALSE;
    error       : BOOL := FALSE;
    status      : WORD := 16#0000;
END_VAR
VAR
END_VAR

// Parameter validation: loLevel must be less than hiLevel
IF loLevel >= hiLevel THEN
    error := TRUE;
    status := 16#8001;
    RETURN;
END_IF;

// Parameter validation: hystWindow must be less than the range between hiLevel and loLevel
IF hystWindow >= (hiLevel - loLevel) THEN
    error := TRUE;
    status := 16#8002;
    RETURN;
END_IF;

// High alarm: trigger when Value exceeds hiLevel, clear when below hiLevel minus hysteresis
IF Value > hiLevel THEN
    hiAlarm := TRUE;
ELSIF Value < (hiLevel - hystWindow) THEN
    hiAlarm := FALSE;
END_IF;

// Low alarm: trigger when Value falls below loLevel, clear when above loLevel plus hysteresis
IF Value < loLevel THEN
    loAlarm := TRUE;
ELSIF Value > (loLevel + hystWindow) THEN
    loAlarm := FALSE;
END_IF;

END_FUNCTION_BLOCK", "new":"FUNCTION_BLOCK AlarmHysteresis
VAR_INPUT
    Value       : REAL;
    hiLevel     : REAL;
    loLevel     : REAL;
    hystWindow  : REAL;
END_VAR
VAR_OUTPUT
    hiAlarm     : BOOL := FALSE;
    loAlarm     : BOOL := FALSE;
    error       : BOOL := FALSE;
    status      : WORD := 16#0000;
END_VAR
VAR
    tmpError    : BOOL := FALSE;
    tmpStatus   : WORD := 16#0000;
END_VAR

IF loLevel >= hiLevel THEN
    tmpError := TRUE;
    tmpStatus := 16#8001;
END_IF;

IF hystWindow >= (hiLevel - loLevel) THEN
    tmpError := TRUE;
    tmpStatus := 16#8002;
END_IF;

error := tmpError;
status := tmpStatus;

IF NOT tmpError THEN
    IF Value > hiLevel THEN
        hiAlarm := TRUE;
    ELSIF Value < (hiLevel - hystWindow) THEN
        hiAlarm := FALSE;
    END_IF;

    IF Value < loLevel THEN
        loAlarm := TRUE;
    ELSIF Value > (loLevel + hystWindow) THEN
        loAlarm := FALSE;
    END_IF;
END_IF;

END_FUNCTION_BLOCK"}]}
